from pathlib import Path
import html,json,shutil
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
ROOT=Path(__file__).resolve().parents[1];APP=ROOT/'FULL_REZZ/app';DOCS=APP/'docs';DOCS.mkdir(exist_ok=True)
font='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';pdfmetrics.registerFont(TTFont('Guide',font));pdfmetrics.registerFont(TTFont('GuideBold',font.replace('Sans.ttf','Sans-Bold.ttf')))
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleR',fontName='GuideBold',fontSize=28,leading=33,textColor=HexColor('#133f47'),spaceAfter=12))
styles.add(ParagraphStyle(name='SubR',fontName='Guide',fontSize=11,leading=16,textColor=HexColor('#43626a'),spaceAfter=18))
styles.add(ParagraphStyle(name='H2R',fontName='GuideBold',fontSize=12,leading=17,textColor=HexColor('#133f47'),spaceBefore=13,spaceAfter=5))
styles.add(ParagraphStyle(name='BodyR',fontName='Guide',fontSize=9.3,leading=14,spaceAfter=8))
pages=[
 ('Install and get started',[
  ('Local Windows package','FULL_REZZ 2.0 targets Windows 10/11 x64. The installer includes Python, Qt, audio decoders and all speech models. No separate Python, Node, browser, FFmpeg, account, model download or service is needed after installation. Plan for 16 GB RAM and 12 GB free disk space. CPU synthesis can take minutes; this is not a real-time avatar.'),
  ('Assemble the installer','Download all four FULL_REZZ_Installer_Part ZIP files. Windows delivery is split because the complete installer exceeds the file delivery limit. Extract every ZIP into the same empty folder. Double-click Assemble_Installer.cmd in that folder. It joins the fragments and checks SHA256 before launching the single FULL_REZZ_2.0_Offline_Setup.exe. Retain the four fragments until verification succeeds.'),
  ('Install and launch','Run the installer as your own user. Choose the installation folder and shortcuts, then open FULL_REZZ. Default install: %LOCALAPPDATA%\\Programs\\FULL_REZZ. This release is unsigned. A native Windows install and launch test has not been performed; the acceptance procedure on page 4 remains required.'),
  ('Where projects live','Project data uses %LOCALAPPDATA%\\VoiceProfileStudio to preserve continuity with earlier releases. Imported audio, authored profiles, sources, exports and render receipts remain there. Back up this entire folder with FULL_REZZ closed. Uninstall removes program files and retains project data.'),
  ('First session','Open Expression & export and choose Load bundled Rebecca, or import your reference ZIP. Inspect the restored recording, region text, review status and source documents. Select the voice profile, enter a short statement, choose the reference style and select Render local speech. Listen to the speech and its actual selected reference before saving a review.')]),
 ('Prepare a reliable voice reference',[
  ('Import and identify','Import WAV, FLAC, MP3, OGG, M4A and supported audio/video containers. Limits: 250 MiB upload, 30 minutes, eight channels and 512 MiB decoded audio. Original files remain preserved. Reference mode treats a recording as one voice; channels select physical channels; automatic grouping produces anonymous ECAPA energy-window/cosine groups, not verified identities.'),
  ('Transcript and regions','Bundled tiny.en transcription is English only and can get names and words wrong. Correct the words manually. Set region start/end, voice label, channel, style and purity review, then Save region edits. Bind the speaker to a character profile. Speaker and character drafts survive switching, but must be saved before export or synthesis.'),
  ('Overlap and cleanup','Separation accepts excerpts up to 30 seconds and outputs two anonymous 8 kHz estimates. Listen for bleed and artifacts. Cleanup is reversible: DC removal, rumble filtering, peak level, boundary fades and optional noise attenuation. A noise-only excerpt must contain no voice or music. Compare Original and Cleaned; conversion cannot repair clipped or missing source bandwidth.'),
  ('Measurements and review','Signal screening reports native-rate levels, clipping, DC and quiet-frame contrast. Band energy reports bass (20-250 Hz), mid (250-2000 Hz), treble (2000-8000 Hz) and upper frequencies where available. These are acoustic measurements, not emotion, identity or likeness scores. A floating signal above full scale is reported separately from PCM clipping.'),
  ('Choose useful conditioning','Use a clean, reviewed single-voice region of 3-12 seconds with its exact spoken words. Requested style selects an available reference label; it does not guarantee emotional performance. Short, noisy, mixed or poorly transcribed references can reduce pronunciation and resemblance. The bundled Rebecca reference is source-attributed; performer likeness and purity have not been verified by listening.')]),
 ('Render, review and preserve context',[
  ('Speech controls','Enter 1-500 characters. Rate: 0.5-2.0. Pitch: -12 to +12 semitones. Volume: -20 to +6 dB. Choose 16 sampling steps for a draft or 32 for fuller sampling; seed is 0-2147483647. Estimated output is capped at 30 seconds. Reference words override the saved annotation; if both are missing, local ASR is used and marked unreviewed.'),
  ('Output and review','F5-TTS v1 Base and Vocos render locally on CPU. Output is 24 kHz FLOAT32 WAV with peak headroom and 5 ms boundary fades. Download the WAV and JSON receipt. Each receipt records selected reference, words, controls, seed, steps, measurements, authored context and review history. Approve or mark Needs revision after listening. A changed audio hash prevents attaching a review. Approval records judgment; it does not train the model.'),
  ('Character and engram files','Biography, persona, prompts, scene notes, canonical endpoint and field sources are authored context. Imported source evidence remains separate from authored facts and retrieved claims. Local TXT, JSON, PDF and DOCX documents can be imported. Internet source retrieval is disabled in the packaged offline application. Engram/context files do not implement autonomous reasoning, new knowledge or consciousness.'),
  ('Export and restoration','Export an immutable reference ZIP with selected profiles, clips, sources, voice logs, character context and quality report. FLOAT32 preserves over-range samples; integer encodings use dither and reject out-of-range audio. Restore packs up to 512 MiB expanded and 10,000 files. IDs are remapped, historical embeddings are retained as history, and the entire original imported ZIP is preserved and included in subsequent exports. Invalid paths, duplicate names or changed reference hashes reject the import transaction.'),
  ('Animation capabilities','The included 12-second Rebecca sequence contains 720 frames at 60 fps, 23 scheduled body drawings and continuous face/limb motion. Use frame stepping and the 24 fps baseline comparison. This demonstrates an authored 2D animation, not arbitrary image-to-motion generation, unseen poses, accurate anime sidesteps, 3D reconstruction or Studio Trigger production equivalence. Audio-energy mouth animation is not phoneme alignment. New speech is exported separately; this release does not automatically regenerate the demonstration for each new statement.')]),
 ('Acceptance, troubleshooting and licenses',[
  ('Before calling it a Windows release','On a clean Windows 10/11 x64 machine, disconnect networking. Assemble and install the package; launch from both shortcuts; load Rebecca; play the 60 fps example; import audio; transcribe, group speakers and separate a short excerpt; render a statement; play/download WAV and receipt; save a review; close/reopen; export and restore a ZIP. Uninstall, reinstall and confirm retained project data. Confirm no runtime, model download, external browser or account is requested.'),
  ('What has been tested','Linux CPU neural inference, loopback API transport, program regression tests, actual 60 fps frame rendering, MP4 decode/timing and installer payload checks are recorded in FULL_REZZ_Audit.md. PE inspection checks declared DLL imports. These checks do not establish native Windows GUI execution, sustained 60 Hz display on your hardware or human listening approval.'),
  ('If something fails','A model checksum error requires reinstalling from the verified installer. If the data folder is locked, close the other FULL_REZZ instance. If synthesis fails, confirm a saved reviewed 3-12 second reference and its actual words; shorten the statement. Review Needs revision output for pronunciation and artifacts. Close with processing idle before backing up. Keep the installer verification report and local data when reporting a problem.'),
  ('Model and software terms','F5-TTS code is MIT; the bundled F5 model weights are CC-BY-NC-4.0, so this bundled model is for noncommercial use. Whisper and Vocos are MIT; SpeechBrain ECAPA and SepFormer model cards specify Apache-2.0. Qt/PySide has LGPL/GPL terms, Python has PSF terms, and Windows CRT and other bundled packages have their own terms. THIRD_PARTY_NOTICES.md and licenses preserve attributions, model cards, upstream addresses and package licenses. Character reference media is user-supplied and remains separately attributed.'),
  ('Quality boundaries','Technical signal checks cannot prove acting quality, voice identity, speaker purity or anime fidelity. Validate those by listening and by comparing against actual licensed motion references. Retain original files and receipts so each judgment can be traced to the exact delivered bytes.')])]
quick=[('Install','Download and extract all four installer ZIPs into one folder. Run Assemble_Installer.cmd; it verifies the reconstructed EXE, then starts setup. Install and open FULL_REZZ. No separately installed runtime or online model download is needed.'),('Restore','In Expression & export, choose Load bundled Rebecca or Import reference pack. Inspect the recording and saved source context. Historical IDs are remapped; original archive bytes remain preserved.'),('Review the reference','Save a 3-12 second single-voice region, its actual words and a purity review. Bind its voice label to the profile. Compare original and cleaned previews before rendering.'),('Render and listen','Select the voice, enter a short statement, choose 16 or 32 steps and Render local speech. Listen to both speech and selected reference. Download the WAV and receipt; save Approve or Needs revision notes.'),('Keep the evidence','Export a reference ZIP, or back up %LOCALAPPDATA%\\VoiceProfileStudio with the program closed. Uninstall retains project data. The 60 fps animation example is a fixed authored test, not arbitrary action generation.'),('Release limits','Windows 10/11 x64 native installation and GUI testing remain pending. F5 weights are noncommercial (CC-BY-NC-4.0). Audio quality and performer likeness require listening review. Full details and acceptance steps are in the user guide.')]
def footer(canvas,doc):
 canvas.setStrokeColor(HexColor('#c7d5d8'));canvas.line(46,43,566,43);canvas.setFont('Guide',8);canvas.setFillColor(HexColor('#43626a'));canvas.drawString(46,29,'FULL_REZZ 2.0 | Offline character & voice studio | 9 October 2026');canvas.drawRightString(566,29,str(doc.page))
def build(name,sections,title):
 story=[]
 for i,(heading,items) in enumerate(sections):
  if i:story.append(PageBreak())
  story.extend([Paragraph(title if i==0 else 'FULL_REZZ',styles['TitleR']),Paragraph(heading,styles['SubR'])])
  for sub,text in items:story.extend([Paragraph(html.escape(sub),styles['H2R']),Paragraph(html.escape(text),styles['BodyR'])])
 SimpleDocTemplate(str(ROOT/name),pagesize=(612,792),leftMargin=46,rightMargin=46,topMargin=45,bottomMargin=57,title=title,author='FULL_REZZ').build(story,onFirstPage=footer,onLaterPages=footer)
build('FULL_REZZ_User_Guide.pdf',pages,'FULL_REZZ User Guide');build('FULL_REZZ_Quick_Start.pdf',[('Quick start - local Windows package',quick)],'FULL_REZZ Quick Start')
for stem,sections in [('User_Guide',pages),('Quick_Start',[('Quick start',quick)])]:
 md='# FULL_REZZ 2.0\n\n9 October 2026\n';body=''
 for heading,items in sections:
  md+='\n## '+heading+'\n';body+='<h2>'+html.escape(heading)+'</h2>'
  for sub,text in items:md+='\n### '+sub+'\n\n'+text+'\n';body+='<h3>'+html.escape(sub)+'</h3><p>'+html.escape(text)+'</p>'
 (DOCS/(stem+'.md')).write_text(md);(DOCS/(stem+'.html')).write_text('<!doctype html><meta charset="utf-8"><title>FULL_REZZ '+stem.replace('_',' ')+'</title><style>body{font:17px/1.6 Segoe UI,sans-serif;max-width:860px;margin:30px auto;padding:24px;color:#143c45}h2{margin-top:45px}h3{margin-bottom:5px}p{margin-top:5px}</style><h1>FULL_REZZ 2.0</h1>'+body)
 shutil.copy2(ROOT/('FULL_REZZ_'+stem.replace('User_Guide','User_Guide').replace('Quick_Start','Quick_Start')+'.pdf'),DOCS/(stem+'.pdf'))
print('Guides created')
